/* ═══ COUNTDOWN BANNER ═══ */
function CountdownBanner() {
  const[time,setTime]=useState({d:0,h:0,m:0,s:0});
  useEffect(()=>{
    const target=new Date("2026-04-01T00:00:00+03:00").getTime();
    const calc=()=>{
      const now=Date.now();const diff=Math.max(0,target-now);
      setTime({d:Math.floor(diff/86400000),h:Math.floor((diff%86400000)/3600000),m:Math.floor((diff%3600000)/60000),s:Math.floor((diff%60000)/1000)});
    };
    calc();const t=setInterval(calc,1000);return()=>clearInterval(t);
  },[]);
  const isLive=time.d===0&&time.h===0&&time.m===0&&time.s===0;
  return(
    <div style={{background:"linear-gradient(135deg,#0d7c3d,#15a050)",borderRadius:14,padding:"16px 20px",maxWidth:540,margin:"0 auto 24px",overflow:"hidden",position:"relative"}}>
      <div style={{position:"absolute",top:0,left:0,right:0,height:"100%",background:"linear-gradient(90deg,transparent,rgba(255,255,255,.04),transparent)",backgroundSize:"200% 100%",animation:"shimmerBg 4s linear infinite"}} />
      <div style={{position:"relative",zIndex:1}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:10,marginBottom:10}}>
          <span style={{fontSize:24}}>⚡</span>
          <div style={{textAlign:"left"}}>
            <div style={{fontSize:15,fontWeight:900,color:"#fff"}}>{isLive?"5G YAYINDA!":"1 NİSAN'DA 5G BAŞLIYOR!"}</div>
            <div style={{fontSize:10,color:"rgba(255,255,255,.75)"}}>Galaxy S25 • iPhone 15 • Vivo Y29S • Samsung A17 5G</div>
          </div>
        </div>
        {!isLive&&(
          <div style={{display:"flex",gap:8,justifyContent:"center"}}>
            {[{v:time.d,l:"GÜN"},{v:time.h,l:"SAAT"},{v:time.m,l:"DAKİKA"},{v:time.s,l:"SANİYE"}].map((u,i)=>(
              <div key={i} style={{background:"rgba(0,0,0,.25)",borderRadius:10,padding:"8px 4px",minWidth:52,textAlign:"center",backdropFilter:"blur(4px)"}}>
                <div style={{fontSize:22,fontWeight:900,color:"#fff",lineHeight:1,animation:u.l==="SANİYE"?"countPulse 1s infinite":"none"}}>{String(u.v).padStart(2,"0")}</div>
                <div style={{fontSize:7,color:"rgba(255,255,255,.6)",fontWeight:700,letterSpacing:1,marginTop:3}}>{u.l}</div>
              </div>
            ))}
          </div>
        )}
        {isLive&&<div style={{textAlign:"center",fontSize:18,fontWeight:900,color:"#fff",animation:"countPulse 1.5s infinite"}}>🎉 5G ARTIK AKTİF!</div>}
      </div>
    </div>
  );
}

/* ═══ PROMO CAROUSEL ═══ */
function PromoCarousel({onNav,dynPromos}){
  const[idx,setIdx]=useState(0);
  const defaultPromos=[
    {title:"📱 Ayın Cihazı",sub:"Samsung Galaxy S26 Ultra",desc:"12 GB RAM • 256 GB • 109.999 TL'den başlayan fiyatlarla!",color:"#1428A0",action:"phone"},
    {title:"📡 En İyi Tarife",sub:"GNÇ Avantaj+ 40 GB",desc:"20+20 GB Sosyal Medya • 1000 DK • 650 TL/ay",color:"#E8A800",action:"tariff"},
    {title:"🏠 Ev İnterneti Fırsatı",sub:"Fiber 15 Ay — 591 TL'den",desc:"100 Mbps'den 1000 Mbps'e kadar • Taahhütlü avantajlı fiyatlar",color:"#00B4D8",action:"internet"},
    {title:"🎁 200 TL Alışveriş Çeki",sub:"Her Faturalı Hat Geçişinde",desc:"Numara taşıma veya yeni hat al, 200 TL çek kazan + iPhone 15 çekilişi!",color:"#25D366",action:"tariff"},
    {title:"⚡ 1 Nisan'da 5G!",sub:"5G Uyumlu Cihazlar Hazır",desc:"Galaxy S25-S26 • iPhone 15-17 • Vivo Y29S • Samsung A17 5G",color:"#0d7c3d",action:"phone"},
  ];
  const promos=(dynPromos&&dynPromos.length>0)?dynPromos:defaultPromos;
  useEffect(()=>{const t=setInterval(()=>setIdx(i=>(i+1)%promos.length),4000);return()=>clearInterval(t)},[promos.length]);
  useEffect(()=>{if(idx>=promos.length)setIdx(0)},[promos.length]);
  const p=promos[idx%promos.length]||promos[0];
  if(!p)return null;
  const hasImg=p.imageUrl&&p.imageUrl.trim();
  return(
    <div style={{position:"relative",overflow:"hidden"}}>
      <div onClick={()=>onNav(p.action)} style={{background:hasImg?"#000":`linear-gradient(135deg,${p.color},${p.color}dd)`,borderRadius:16,padding:"20px 24px",cursor:"pointer",transition:"all .5s ease",minHeight:100,display:"flex",flexDirection:"column",justifyContent:"center",boxShadow:`0 4px 20px ${p.color}33`,position:"relative",overflow:"hidden"}}>
        {/* Arka plan resmi — JPG PNG GIF WebP SVG desteklenir, GIF animasyonlu çalışır */}
        {hasImg&&<img src={p.imageUrl} alt="" onError={e=>e.target.style.display='none'} style={{position:"absolute",inset:0,width:"100%",height:"100%",objectFit:"cover"}}/>}
        {/* Metin okunurluğu için karartma */}
        {hasImg&&<div style={{position:"absolute",inset:0,background:`linear-gradient(135deg,${p.color||"rgba(0,0,0,.7)"}bb,rgba(0,0,0,.3))`}}/>}
        <div style={{position:"relative",zIndex:1}}>
          <div style={{fontSize:11,color:"rgba(255,255,255,.7)",fontWeight:600,marginBottom:4,textTransform:"uppercase",letterSpacing:1}}>{p.title}</div>
          <div style={{fontSize:20,fontWeight:900,color:"#fff",marginBottom:4}}>{p.sub}</div>
          <div style={{fontSize:12,color:"rgba(255,255,255,.85)",lineHeight:1.4}}>{p.desc}</div>
        </div>
      </div>
      {/* Dots */}
      <div style={{display:"flex",justifyContent:"center",gap:6,marginTop:10}}>
        {promos.map((_,i)=>(<div key={i} onClick={()=>setIdx(i)} style={{width:i===idx?20:8,height:8,borderRadius:4,background:i===idx?"var(--acc)":"var(--brd)",cursor:"pointer",transition:"all .3s"}}/>))}
      </div>
    </div>
  );
}

